package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var taxFile *os.File
var taxScanner *bufio.Scanner
var currentRec TaxRec
var eofReached bool = false

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func formatEdited(d decimal.Decimal, pic string) string {
	// count digit placeholders and locate dot
	dotIdx := strings.Index(pic, ".")
	intPic := pic
	fracPic := ""
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	}
	// integer digit count
	intDigitsCount := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigitsCount++
		}
	}
	fracDigitsCount := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracDigitsCount++
		}
	}

	// work with absolute value (no negatives in this program)
	if d.IsNegative() {
		d = d.Neg()
	}
	// ensure scale
	// get integer part and fractional part
	// truncate toward zero to required fractional scale
	// d already has scale 2 for these fields
	// extract integer string with leading zeros/truncation
	intPart := d.Truncate(0)
	// Use string of intPart without sign
	intStr := intPart.StringFixed(0) // no fractional
	// Remove possible minus and decimal
	if intStr == "" {
		intStr = "0"
	}
	// intStr may contain '-'? already abs
	// intStr is like "1000"
	// Build padded/truncated integer digits of length intDigitsCount
	var intDigits string
	if len(intStr) > intDigitsCount {
		intDigits = intStr[len(intStr)-intDigitsCount:]
	} else {
		intDigits = strings.Repeat("0", intDigitsCount-len(intStr)) + intStr
	}

	// fractional digits
	var fracDigits string
	if fracDigitsCount > 0 {
		// get fractional part as 0..99
		// Use d - intPart
		fracVal := d.Sub(intPart)
		if fracVal.IsNegative() {
			fracVal = fracVal.Neg()
		}
		// shift
		shifted := fracVal.Shift(int32(fracDigitsCount)) // *10^n
		// Truncate
		shifted = shifted.Truncate(0)
		fracInt := shifted.IntPart()
		// format with leading zeros
		fracStr := fmt.Sprintf("%d", fracInt)
		if len(fracStr) > fracDigitsCount {
			fracStr = fracStr[len(fracStr)-fracDigitsCount:]
		} else if len(fracStr) < fracDigitsCount {
			fracStr = strings.Repeat("0", fracDigitsCount-len(fracStr)) + fracStr
		}
		fracDigits = fracStr
	}

	// find first non-zero in intDigits
	firstNonZero := -1
	for i, ch := range intDigits {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}
	if firstNonZero == -1 {
		// all zero => last digit is the required zero (the '9')
		firstNonZero = intDigitsCount - 1
	}

	// Build integer part of picture
	var out []rune
	digitIdx := 0
	// To decide comma suppression, need to know if any non-zero has been output yet
	// We can determine by checking if digitIdx <= firstNonZero and intDigits[digitIdx]=='0' for Z positions
	// Simpler: if firstNonZero >= digitIdx for upcoming digits, still suppressed
	// For comma: if digitIdx > firstNonZero then we have already passed first non-zero => show comma
	// else if there exists a non-zero before comma, show comma
	// So comma shown iff firstNonZero < digitIdx  (meaning first non-zero is before the comma's next digit block) ??? Need more precise.
	// Use flag emittedNonZero
	emittedNonZero := false
	// Actually we can update emittedNonZero when we emit a non-zero digit
	// For comma, if emittedNonZero then ',' else ' '
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			dgt := rune(intDigits[digitIdx])
			digitIdx++
			if ch == 'Z' {
				if !emittedNonZero && dgt == '0' && digitIdx-1 < firstNonZero {
					out = append(out, ' ')
				} else {
					out = append(out, dgt)
					if dgt != '0' {
						emittedNonZero = true
					} else {
						// dgt == '0' but if we are at or past firstNonZero, zero is significant
						// If firstNonZero == digitIdx-1 and dgt=='0' this is the single zero -> considered emitted
						// but emittedNonZero remains false for leading zeros? For comma logic, zero alone should count as emitted?
						// For value 0, firstNonZero is last index, emittedNonZero will become false until last digit.
						// The integer zero's '0' should cause following commas? There are no commas after it.
						// So treat this zero as emitted if it's at firstNonZero
						if digitIdx-1 >= firstNonZero {
							// this zero is part of significant tail (e.g., 1,000) - not affecting comma before
							// but after firstNonZero all zeros are significant, and emittedNonZero should be true
							emittedNonZero = true
						}
					}
				}
			} else { // '9'
				out = append(out, dgt)
				// '9' always counts as emitted for comma purposes if it's non-zero or zero? But 9 is always last, no comma after
				if dgt != '0' {
					emittedNonZero = true
				} else {
					// if this 9 is the only zero (value zero) then it's the significant zero
					// still consider emitted
					emittedNonZero = true
				}
			}
		} else if ch == ',' {
			if emittedNonZero {
				out = append(out, ',')
			} else {
				// check if firstNonZero is before the remaining digits? Actually if first non-zero is beyond this comma,
				// then we are still in leading suppression
				// Use emittedNonZero false => space
				// But need to handle case like 1,000 where firstNonZero is before comma -> emittedNonZero true => ','
				out = append(out, ' ')
			}
		} else {
			out = append(out, ch)
		}
	}
	if dotIdx >= 0 {
		out = append(out, '.')
		fracIdx := 0
		for _, ch := range fracPic {
			if ch == 'Z' || ch == '9' {
				out = append(out, rune(fracDigits[fracIdx]))
				fracIdx++
			} else {
				out = append(out, ch)
			}
		}
	}
	return string(out)
}

func moveToEdited(src decimal.Decimal, pic string) string {
	return formatEdited(src, pic)
}

func parseIncome(s string) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// s contains digits only
	// PIC 9(6)V99 => 8 digits, implied 2 decimal
	// parse as integer then shift -2
	// keep only digits
	digits := ""
	for _, r := range s {
		if r >= '0' && r <= '9' {
			digits += string(r)
		}
	}
	if digits == "" {
		return decimal.NewFromInt(0)
	}
	d, _ := decimal.NewFromString(digits)
	// shift -2
	d = d.Shift(-2)
	return d
}

func READ_PARA() {
	if taxScanner == nil {
		WsEofFlag = "Y"
		eofReached = true
		return
	}
	if taxScanner.Scan() {
		line := taxScanner.Text()
		// PAD with spaces to 13
		if len(line) < 13 {
			line = line + strings.Repeat(" ", 13-len(line))
		} else if len(line) > 13 {
			line = line[:13]
		}
		trId := line[0:5]
		trIncomeStr := line[5:13]
		currentRec.TrId = trId
		currentRec.TrIncome = parseIncome(trIncomeStr)
	} else {
		WsEofFlag = "Y"
		eofReached = true
	}
}

func PROCESS_PARA() {
	tenThousand := decimal.NewFromInt(10000)
	fortyThousand := decimal.NewFromInt(40000)
	rate10 := decimal.NewFromFloat(0.10)
	rate20 := decimal.NewFromFloat(0.20)
	rate30 := decimal.NewFromFloat(0.30)
	thousand := decimal.NewFromInt(1000)
	sevenThousand := decimal.NewFromInt(7000)

	if currentRec.TrIncome.Cmp(tenThousand) <= 0 {
		// COMPUTE WS-TAX ROUNDED = TR-INCOME * 0.10
		WsTax = currentRec.TrIncome.Mul(rate10).Round(2)
	} else {
		if currentRec.TrIncome.Cmp(fortyThousand) <= 0 {
			WsTax = thousand.Add(currentRec.TrIncome.Sub(tenThousand).Mul(rate20)).Round(2)
		} else {
			WsTax = sevenThousand.Add(currentRec.TrIncome.Sub(fortyThousand).Mul(rate30)).Round(2)
		}
	}
	WsNet = currentRec.TrIncome.Sub(WsTax)
	WsTotalTax = WsTotalTax.Add(WsTax)
	WsCount = WsCount + 1
	WsIncEd = moveToEdited(currentRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = moveToEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = moveToEdited(WsNet, "ZZZ,ZZ9.99")
	// DISPLAY TR-ID " " WS-INC-ED " " WS-TAX-ED " " WS-NET-ED
	fmt.Printf("%s %s %s %s\n", currentRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
	READ_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT TAX-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		WsEofFlag = "Y"
		eofReached = true
	} else {
		taxFile = f
		taxScanner = bufio.NewScanner(f)
		READ_PARA()
		for !isInputDone() {
			PROCESS_PARA()
		}
		taxFile.Close()
	}
	WsTotalEd = moveToEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	// DISPLAY "TAXPAYERS: " WS-COUNT " TOTAL TAX: " WS-TOTAL-ED
	// WS-COUNT is PIC 9(3) zero-padded to 3 digits
	countStr := fmt.Sprintf("%03d", WsCount)
	// If count exceeds 3 digits, keep low-order digits (COBOL truncation)
	if len(countStr) > 3 {
		countStr = countStr[len(countStr)-3:]
	}
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}

func main() {
	MAIN_PARA()
}
